"""Image build only: classify a new DB generated by the embedded daemon."""
import json
import os
import signal
import sqlite3
import subprocess
import tempfile
import time
from pathlib import Path
from backup.projection import fingerprint

with tempfile.TemporaryDirectory() as directory:
    env={'HOME':directory,'PATH':os.environ['PATH'],'LAUNCHPAD_PORT':'17319'}
    process=subprocess.Popen(['/usr/local/bin/launchpad','daemon'],env=env,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True)
    try:
        db=Path(directory)/'.local/share/launchpad/state.db'
        for _ in range(100):
            if process.poll() is not None: raise RuntimeError('Schema daemon exited')
            if db.exists():
                try:
                    with sqlite3.connect(db) as connection:
                        connection.execute('SELECT archived_done FROM session LIMIT 1')
                        schema=fingerprint(connection)
                    Path('schema.json').write_text(json.dumps({'state_schema':schema}))
                    break
                except sqlite3.OperationalError: pass
            time.sleep(.1)
        else: raise RuntimeError('Schema daemon did not initialize')
    finally:
        os.killpg(process.pid,signal.SIGTERM)
        try: process.wait(timeout=10)
        except subprocess.TimeoutExpired:
            os.killpg(process.pid,signal.SIGKILL);process.wait()
